public partial class BaseTest
{
        public object preciseEqualPositionStr(Exchange exchange, object result, object key, object expected)
        {
            return Precise.stringEq(exchange.safeString(result, key), expected);
        }
        public void testSafePosition()
        {
            var exchange = new ccxt.Exchange(new Dictionary<string, object>() {
                { "id", "sampleexchange" },
            });
            // CASE 1 - isolated linear long: derive maintenanceMargin
            // entryMargin = 100, entryPrice = 1000, liquidationPrice = 910, contracts = 2, contractSize = 0.5
            // lossFromEntry = (1000 - 910) * 2 * 0.5 = 90 -> maintenanceMargin = 100 - 90 = 10
            Dictionary<string, object> pos1 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "liquidationPrice", 910 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "collateral", 100 },
                { "initialMargin", 100 },
            };
            Dictionary<string, object> res1 = exchange.safePosition(pos1);
            Assert(preciseEqualPositionStr(exchange, res1, "maintenanceMargin", "10"));
            // CASE 2 - isolated linear short: derive liquidationPrice
            // entryMargin = 100, maintenanceMargin = 10, entryPrice = 1000, contracts = 2, contractSize = 0.5
            // bufferPerUnit = (100 - 10) / (2 * 0.5) = 90 -> liquidationPrice = 1000 + 90 = 1090
            Dictionary<string, object> pos2 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "short" },
                { "entryPrice", 1000 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "collateral", 100 },
                { "initialMargin", 100 },
                { "maintenanceMargin", 10 },
            };
            Dictionary<string, object> res2 = exchange.safePosition(pos2);
            Assert(preciseEqualPositionStr(exchange, res2, "liquidationPrice", "1090"));
            // CASE 3 - isolated linear long: derive entryPrice
            Dictionary<string, object> pos3 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "liquidationPrice", 910 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "collateral", 100 },
                { "initialMargin", 100 },
                { "maintenanceMargin", 10 },
            };
            Dictionary<string, object> res3 = exchange.safePosition(pos3);
            Assert(preciseEqualPositionStr(exchange, res3, "entryPrice", "1000"));
            // CASE 4 - isolated linear long: derive contracts
            Dictionary<string, object> pos4 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "liquidationPrice", 910 },
                { "contractSize", 0.5 },
                { "collateral", 100 },
                { "initialMargin", 100 },
                { "maintenanceMargin", 10 },
            };
            Dictionary<string, object> res4 = exchange.safePosition(pos4);
            Assert(preciseEqualPositionStr(exchange, res4, "contracts", "2"));
            // CASE 5 - isolated linear long: derive contractSize
            Dictionary<string, object> pos5 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "liquidationPrice", 910 },
                { "contracts", 2 },
                { "collateral", 100 },
                { "initialMargin", 100 },
                { "maintenanceMargin", 10 },
            };
            Dictionary<string, object> res5 = exchange.safePosition(pos5);
            Assert(preciseEqualPositionStr(exchange, res5, "contractSize", "0.5"));
            // CASE 6 - isolated linear long: derive collateral and initialMargin
            Dictionary<string, object> pos6 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "liquidationPrice", 910 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "maintenanceMargin", 10 },
            };
            Dictionary<string, object> res6 = exchange.safePosition(pos6);
            Assert(preciseEqualPositionStr(exchange, res6, "initialMargin", "100"));
            Assert(preciseEqualPositionStr(exchange, res6, "collateral", "100"));
            // CASE 7 - isolated linear with unrealizedPnl included in collateral
            // collateral = 115, unrealizedPnl = 15 -> entryMargin = 100 -> maintenanceMargin = 10
            Dictionary<string, object> pos7 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "liquidationPrice", 910 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "collateral", 115 },
                { "unrealizedPnl", 15 },
            };
            Dictionary<string, object> res7 = exchange.safePosition(pos7);
            Assert(preciseEqualPositionStr(exchange, res7, "maintenanceMargin", "10"));
            // CASE 8 - cross margin position must not derive isolated maintenanceMargin
            Dictionary<string, object> pos8 = new Dictionary<string, object>() {
                { "marginMode", "cross" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "liquidationPrice", 910 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "collateral", 100 },
                { "initialMargin", 100 },
            };
            Dictionary<string, object> res8 = exchange.safePosition(pos8);
            Assert(isEqual(exchange.safeValue(res8, "maintenanceMargin"), null));
            // CASE 9 - cross margin linear position derives notional, unrealizedPnl, initialMarginPercentage, initialMargin, maintenanceMargin, marginRatio, percentage
            Dictionary<string, object> pos9 = new Dictionary<string, object>() {
                { "marginMode", "cross" },
                { "side", "long" },
                { "entryPrice", 1000 },
                { "markPrice", 1050 },
                { "contracts", 2 },
                { "contractSize", 0.5 },
                { "leverage", 10 },
                { "maintenanceMarginPercentage", 0.01 },
                { "collateral", 210 },
            };
            Dictionary<string, object> res9 = exchange.safePosition(pos9);
            Assert(preciseEqualPositionStr(exchange, res9, "notional", "1050"));
            Assert(preciseEqualPositionStr(exchange, res9, "unrealizedPnl", "50"));
            Assert(preciseEqualPositionStr(exchange, res9, "initialMarginPercentage", "0.1"));
            Assert(preciseEqualPositionStr(exchange, res9, "initialMargin", "105"));
            Assert(preciseEqualPositionStr(exchange, res9, "maintenanceMargin", "10.5"));
            Assert(preciseEqualPositionStr(exchange, res9, "marginRatio", "0.05"));
            Assert(preciseEqualPositionStr(exchange, res9, "percentage", "47.61"));
            // CASE 10 - cross margin position derives leverage, maintenanceMarginPercentage, and markPrice
            Dictionary<string, object> pos10 = new Dictionary<string, object>() {
                { "marginMode", "cross" },
                { "side", "short" },
                { "notional", 2000 },
                { "contracts", 4 },
                { "contractSize", 0.5 },
                { "initialMarginPercentage", 0.05 },
                { "maintenanceMargin", 20 },
            };
            Dictionary<string, object> res10 = exchange.safePosition(pos10);
            Assert(preciseEqualPositionStr(exchange, res10, "markPrice", "1000"));
            Assert(preciseEqualPositionStr(exchange, res10, "leverage", "20"));
            Assert(preciseEqualPositionStr(exchange, res10, "initialMargin", "100"));
            Assert(preciseEqualPositionStr(exchange, res10, "maintenanceMarginPercentage", "0.01"));
            // CASE 11 - negative collateral position must not derive initialMargin or maintenanceMargin
            Dictionary<string, object> pos11 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 74.35 },
                { "liquidationPrice", 60.07 },
                { "markPrice", 74.43 },
                { "notional", 7.443 },
                { "leverage", 5 },
                { "contracts", 1 },
                { "contractSize", 0.1 },
                { "collateral", -3.967 },
                { "unrealizedPnl", 0.008 },
            };
            Dictionary<string, object> res11 = exchange.safePosition(pos11);
            Assert(isEqual(exchange.safeValue(res11, "initialMargin"), null));
            Assert(isEqual(exchange.safeValue(res11, "maintenanceMargin"), null));
            Assert(isEqual(exchange.safeValue(res11, "positionMargin"), null));
            // CASE 12 - margin given: collateral = margin + unrealizedPnl, and margin drives the liquidation equation
            Dictionary<string, object> pos12 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "long" },
                { "entryPrice", 100 },
                { "liquidationPrice", 90.5 },
                { "contracts", 1 },
                { "contractSize", 1 },
                { "positionMargin", 10 },
                { "unrealizedPnl", 2 },
            };
            Dictionary<string, object> res12 = exchange.safePosition(pos12);
            Assert(preciseEqualPositionStr(exchange, res12, "collateral", "12"));
            Assert(preciseEqualPositionStr(exchange, res12, "maintenanceMargin", "0.5"));
            // CASE 13 - isolated collateral given without margin: margin = collateral - unrealizedPnl
            Dictionary<string, object> pos13 = new Dictionary<string, object>() {
                { "marginMode", "isolated" },
                { "side", "short" },
                { "entryPrice", 100 },
                { "contracts", 2 },
                { "contractSize", 1 },
                { "initialMargin", 20 },
                { "collateral", 17 },
                { "unrealizedPnl", -3 },
            };
            Dictionary<string, object> res13 = exchange.safePosition(pos13);
            Assert(preciseEqualPositionStr(exchange, res13, "positionMargin", "20"));
        }
}